function isPalindrome(s) {
  const isAlnum = (c) => /[a-z0-9]/i.test(c);
  let left = 0;
  let right = s.length - 1;
  while (left < right) {
    if (!isAlnum(s[left])) {
      left++; // skip a non-alphanumeric char on the left
    } else if (!isAlnum(s[right])) {
      right--; // skip a non-alphanumeric char on the right
    } else if (s[left].toLowerCase() !== s[right].toLowerCase()) {
      return false; // mismatch: not a palindrome
    } else {
      left++; // match: move both pointers inward
      right--;
    }
  }
  return true;
}

def is_palindrome(s: str) -> bool:
    left, right = 0, len(s) - 1
    while left < right:
        if not s[left].isalnum():
            left += 1  # skip a non-alphanumeric char on the left
        elif not s[right].isalnum():
            right -= 1  # skip a non-alphanumeric char on the right
        elif s[left].lower() != s[right].lower():
            return False  # mismatch
        else:
            left += 1  # match: move both pointers inward
            right -= 1
    return True

public boolean isPalindrome(String s) {
    int left = 0, right = s.length() - 1;
    while (left < right) {
        char a = s.charAt(left), b = s.charAt(right);
        if (!Character.isLetterOrDigit(a)) {
            left++; // skip a non-alphanumeric char on the left
        } else if (!Character.isLetterOrDigit(b)) {
            right--; // skip a non-alphanumeric char on the right
        } else if (Character.toLowerCase(a) != Character.toLowerCase(b)) {
            return false; // mismatch
        } else {
            left++; // match: move both pointers inward
            right--;
        }
    }
    return true;
}

function twoSumSorted(numbers, target) {
  let left = 0;
  let right = numbers.length - 1;
  while (left < right) {
    const sum = numbers[left] + numbers[right];
    if (sum === target) {
      return [left + 1, right + 1]; // 1-based answer
    }
    if (sum < target) {
      left++; // too small: only a bigger left value can help
    } else {
      right--; // too big: only a smaller right value can help
    }
  }
  return [-1, -1]; // unreachable when a solution is guaranteed
}

