function maxArea(height) {
  let left = 0;
  let right = height.length - 1;
  let best = 0;
  while (left < right) {
    const h = Math.min(height[left], height[right]);
    best = Math.max(best, h * (right - left));
    if (height[left] < height[right]) {
      left++; // left is the shorter wall: moving right can't help it
    } else {
      right--; // right is the shorter (or equal) wall
    }
  }
  return best;
}

def max_area(height):
