    }
}

function merge(nums1, m, nums2, n) {
  let i = m - 1; // last real value in nums1
  let j = n - 1; // last value in nums2
  let k = m + n - 1; // next slot to fill, from the back
  while (j >= 0) {
    if (i >= 0 && nums1[i] > nums2[j]) {
      nums1[k] = nums1[i]; // nums1 has the larger value
      i--;
    } else {
      nums1[k] = nums2[j]; // nums2 has the larger (or equal) value
      j--;
    }
    k--;
  }
}

